// Auto-generated ChanSight OGP image (1200x630 PNG) from assets/chansight-ogp.png

const OG_IMAGE_PNG_BASE64 =
  "";

let cachedOgImage: Uint8Array<ArrayBuffer> | undefined;

export function getOgImagePngBytes(): Uint8Array<ArrayBuffer> {
  if (!cachedOgImage) {
    const bin = atob(OG_IMAGE_PNG_BASE64);
    const bytes = new Uint8Array(new ArrayBuffer(bin.length));
    for (let i = 0; i < bin.length; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    cachedOgImage = bytes;
  }
  return cachedOgImage;
}
